import { useRef, useState } from 'react';

export interface PageCacheBaseState {
  cachedHtml: string | null;
  isCacheChecking: boolean;
  isCacheHit: boolean;
  isStaleHit: boolean;
  shouldRevalidate: boolean;
  pageHash: string | null;
  setCachedHtml: React.Dispatch<React.SetStateAction<string | null>>;
  setIsCacheChecking: React.Dispatch<React.SetStateAction<boolean>>;
  setIsCacheHit: React.Dispatch<React.SetStateAction<boolean>>;
  setIsStaleHit: React.Dispatch<React.SetStateAction<boolean>>;
  setShouldRevalidate: React.Dispatch<React.SetStateAction<boolean>>;
  setPageHash: React.Dispatch<React.SetStateAction<string | null>>;
  checkedHashRef: React.MutableRefObject<string>;
  abortControllerRef: React.MutableRefObject<AbortController | null>;
}

export const usePageCacheBaseState = (): PageCacheBaseState => {
  const [cachedHtml, setCachedHtml] = useState<string | null>(null);
  const [isCacheChecking, setIsCacheChecking] = useState(true);
  const [isCacheHit, setIsCacheHit] = useState(false);
  const [isStaleHit, setIsStaleHit] = useState(false);
  const [shouldRevalidate, setShouldRevalidate] = useState(false);
  const [pageHash, setPageHash] = useState<string | null>(null);

  const checkedHashRef = useRef<string>('');
  const abortControllerRef = useRef<AbortController | null>(null);

  return {
    cachedHtml,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    pageHash,
    setCachedHtml,
    setIsCacheChecking,
    setIsCacheHit,
    setIsStaleHit,
    setShouldRevalidate,
    setPageHash,
    checkedHashRef,
    abortControllerRef,
  };
};
